Rekening r = new Rekening("Sari", 1000);
cek(!r.tarik(1001), "tarik melebihi saldo harus false");
sama(1000, r.getSaldo());

Rekening r = new Rekening("Sari", 1000);
cek(!r.setor(0) && !r.setor(-5), "setor 0 atau negatif harus false");
cek(!r.tarik(0) && !r.tarik(-5), "tarik 0 atau negatif harus false");
sama(1000, r.getSaldo());

