// Nilai.java
public class Nilai {
    private int angka;

    public Nilai(int angka) {
        setAngka(angka);
    }

    public boolean setAngka(int angka) {
        if (angka < 0 || angka > 100) {
            return false;
        }
        this.angka = angka;
        return true;
    }

    public int getAngka() {
        return angka;
    }

    public String huruf() {
        if (angka >= 85) {
            return "A";
        } else if (angka >= 70) {
            return "B";
        } else if (angka >= 55) {
            return "C";
        } else if (angka >= 40) {
            return "D";
        }
        return "E";
    }
}

